mapper.select:
       select cashpay.pay_type  partType, 
      cashpay.pay_cycle partCycle  
 from FIN_CASH_PAY_RULE cashpay, FIN_CASH_INFO cashinfo

where cashpay.CASH_ID = cashinfo.CASH_ID
  and cashinfo.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
  and cashinfo.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
  and cashinfo.FINPROD_ID = #{prodId,jdbcType=VARCHAR}
  and cashpay.eff_date = (
 select max(eff_date)
         from FIN_CASH_PAY_RULE
        where CASH_ID = (  select CASH_ID
                 from FIN_CASH_INFO cashinfo
                where FINPROD_ID = #{prodId,jdbcType=VARCHAR}
                  and cashinfo.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
                  and cashinfo.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}))
